using System;
using System.Collections.ObjectModel;
using System.Threading.Tasks;
using System.Windows.Input;
using RagnarokCompanion.Models;
using RagnarokCompanion.Services;
namespace RagnarokCompanion.ViewModels;
public sealed partial class BuildViewModel
{
 bool authorizationDeferred,profileDirty;public bool FirebaseOnline=>System.Net.NetworkInformation.NetworkInterface.GetIsNetworkAvailable();
 public bool IsSignedIn=>community is FirestoreBuildGateway f&&f.Session.SignedIn;
 public bool IsSignedOut=>!IsSignedIn;
 public string GoogleAccountName=>community is FirestoreBuildGateway f&&f.Session.SignedIn?BuildPublicName.Clean(f.Session.Name):"Não conectada";
 public string AccountLabel=>IsSignedIn?BuildPublicName.Clean(discordNickname.Length>0?discordNickname:GoogleAccountName):"";
 void NotifyAccount(){foreach(var p in new[]{nameof(IsSignedIn),nameof(IsSignedOut),nameof(AccountLabel),nameof(GoogleAccountName)})Changed(p);if(community is FirestoreBuildGateway f)f.PublicAuthorName=AccountLabel;}
 void InitializeAuthentication(){if(community is FirestoreBuildGateway f){f.Session.StateChanged+=SessionStateChanged;_ = RestoreAuthorization();}}
 async void SessionStateChanged(){NotifyAccount();if(!IsSignedIn){IsAdmin=false;PendingBuilds.Clear();SelectedSubmission=null;CloudOwn.Clear();OwnReviewSummary="";Changed(nameof(OwnReviewSummary));}else{ReadDiscordProfile();await RestoreAuthorization();}RefreshStarIdentity();}
 async Task RestoreAuthorization(){if(community is not FirestoreBuildGateway f||!f.Session.SignedIn)return;if(!FirebaseOnline){authorizationDeferred=true;IsAdmin=false;NotifyAccount();return;}authorizationDeferred=false;string uid=f.Session.UserId;try{bool allowed=await f.CheckAdmin(cancellation.Token);if(f.Session.SignedIn&&f.Session.UserId==uid)IsAdmin=allowed;}catch{IsAdmin=false;}NotifyAccount();await SyncCommunityProfile();}
 async Task SyncCommunityProfile(){if(community is not FirestoreBuildGateway f||!f.Session.SignedIn)return;if(!FirebaseOnline)return;string uid=f.Session.UserId;var state=repository.SyncState("profile:"+uid);if(state!=null&&state.Data==discordNickname&&DateTimeOffset.UtcNow-state.Updated<TimeSpan.FromHours(12))return;try{var profile=await f.SavePublicProfile(discordNickname,false,cancellation.Token);if(!f.Session.SignedIn||f.Session.UserId!=uid)return;if(profile.DiscordNickname!=discordNickname){repository.SaveDiscordNickname(f.Session.UserId,profile.DiscordNickname);discordNickname=profile.DiscordNickname;DiscordNicknameInput=discordNickname;}profileDirty=false;repository.SaveSyncState("profile:"+uid,new(discordNickname,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,0),"profile");NotifyAccount();}catch{}} public string OwnReviewSummary {get;private set;}="";
 public ObservableCollection<PlayerBuild> CloudOwn {get;}=new();
 public ICommand GoogleLoginCommand=>new RelayCommand(async _=>await LoginGoogle());
 public ICommand GoogleLogoutCommand=>new RelayCommand(_=>{if(Busy)return;if(community is FirestoreBuildGateway f){IsAdmin=false;PendingBuilds.Clear();SelectedSubmission=null;f.Session.SignOut();NeedsDiscordNickname=false;discordNickname="";OwnReviewSummary="";Changed(nameof(OwnReviewSummary));ownFetched=default;ownAccount="";ownCursor=null;Changed(nameof(HasMoreOwn));CloudOwn.Clear();NotifyAccount();Tell("Conta desconectada. Rascunhos locais preservados.");}});
 public ICommand FetchOwnCommand=>new RelayCommand(async _=>await FetchOwn());
 public ICommand OpenOwnCommand=>new RelayCommand(async value=>{if(Busy||value is not PlayerBuild b)return;Busy=true;try{if(communitySync!=null)b=await communitySync.OwnContent(b,cancellation.Token);OpenSaved(b);}catch(Exception e){Tell(e.Message);}finally{Busy=false;}});
 DateTimeOffset ownFetched;string ownAccount="";string? ownCursor;public bool HasMoreOwn=>ownCursor!=null;public ICommand MoreOwnCommand=>new RelayCommand(async _=>await FetchOwn(true));
 void ReadOwnCache(){try{if(community is FirestoreBuildGateway f&&f.Session.SignedIn){foreach(var b in repository.CachedOwn(f.Session.UserId))CloudOwn.Add(b);var state=repository.SyncState("own-list:"+f.Session.UserId);ownFetched=state?.Updated??default;ownAccount=f.Session.UserId;ownCursor=state?.Data.Length>0?state.Data:null;Changed(nameof(HasMoreOwn));}}catch{}}
 string discordNickname="",nicknameInput="";bool needsDiscordNickname;
 public bool NeedsDiscordNickname {get=>needsDiscordNickname;private set{needsDiscordNickname=value;Changed();}}
 public string DiscordNicknameInput {get=>nicknameInput;set{nicknameInput=value??"";Changed();}}
 public ICommand SaveDiscordNicknameCommand=>new RelayCommand(async _=>{if(community is not FirestoreBuildGateway f||!f.Session.SignedIn)return;try{repository.SaveDiscordNickname(f.Session.UserId,DiscordNicknameInput);discordNickname=DiscordNicknameInput.Trim();NeedsDiscordNickname=false;NotifyAccount();if(!FirebaseOnline){profileDirty=true;Tell("Perfil salvo localmente; será sincronizado ao reconectar.");return;}await f.SavePublicProfile(discordNickname,true,cancellation.Token);repository.SaveSyncState("profile:"+f.Session.UserId,new(discordNickname,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,0),"profile");Tell("Perfil da comunidade atualizado.");}catch(Exception e){Tell(e.Message);}});
 public ICommand EditDiscordNicknameCommand=>new RelayCommand(_=>{if(community is FirestoreBuildGateway f&&f.Session.SignedIn){DiscordNicknameInput=discordNickname;NeedsDiscordNickname=true;}});
 void ReadDiscordProfile(){if(community is FirestoreBuildGateway f&&f.Session.SignedIn){discordNickname=repository.DiscordNickname(f.Session.UserId);DiscordNicknameInput=discordNickname;NeedsDiscordNickname=false;NotifyAccount();}}
 async Task LoginGoogle(){if(!FirebaseOnline){Tell("Conecte-se para entrar com Google.");return;}if(Busy||community is not FirestoreBuildGateway f)return;Busy=true;try{await f.Session.Login(cancellation.Token);OwnReviewSummary="";Changed(nameof(OwnReviewSummary));CloudOwn.Clear();ReadOwnCache();ReadDiscordProfile();NotifyAccount();Tell("Login concluído. Nenhuma build foi publicada.");}catch(OperationCanceledException){Tell("Login cancelado ou tempo esgotado.");}catch(Exception){Tell("Não foi possível entrar. Confira a configuração Web e a página de login publicada no Firebase Hosting.");}finally{Busy=false;}}
 async Task FetchOwn(bool more=false){if(!FirebaseOnline){Tell("Sem conexão: publicações próprias carregadas do cache.");return;}if(Busy||community is not FirestoreBuildGateway f)return;if(!more&&DateTimeOffset.UtcNow-ownFetched<TimeSpan.FromMinutes(5)&&ownAccount==f.Session.UserId){Tell("Lista em cache; aguarde cinco minutos para sincronizar novamente.");return;}Busy=true;try{if(more&&ownCursor==null)return;var builds=await f.Own(cancellation.Token,more?ownCursor:null);if(more)builds=System.Linq.Enumerable.ToList(System.Linq.Enumerable.Select(System.Linq.Enumerable.GroupBy(System.Linq.Enumerable.Concat(CloudOwn,builds),b=>b.Id),g=>System.Linq.Enumerable.Last(g)));ownCursor=f.OwnCursor;Changed(nameof(HasMoreOwn));repository.SaveSyncState("own-list:"+f.Session.UserId,new(ownCursor??"",DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,0),"own-list");OwnReviewSummary=more?OwnReviewSummary+Environment.NewLine+f.OwnReviewSummary:f.OwnReviewSummary;Changed(nameof(OwnReviewSummary));repository.CacheOwn(f.Session.UserId,builds);CloudOwn.Clear();foreach(var b in builds)CloudOwn.Add(b);ownFetched=DateTimeOffset.UtcNow;ownAccount=f.Session.UserId;Tell("Suas publicações carregadas. Builds aprovadas podem ser atualizadas diretamente pelo criador.");}catch(Exception e){Tell(e.Message);}finally{Busy=false;NotifyAccount();}}
}
